#regenerates src/Constants.sol
import hashlib
e=[b"\0"*32]*257
for d in range(255,-1,-1): e[d]=hashlib.sha256(b"NODE"+e[d+1]+e[d+1]).digest()
p=0x1a0111ea397fe69a4b1ba7b6434bacd764774b84f38512bf6730d2a0f6b0f6241eabfffeb153ffffb9feffffffffaaab
gx=0x17f1d3a73197d7942695638c4fa9ac0fc3688c4f9774b905a14e3a3f171bac586c55e83ff97a1aeffb3af00adb22c6bb
gy=0x08b3f481e3aaa0f1a09e30ed741d8ae4fcf5e095d5d00af600db18cb2c04b3edd03cc744a2888ae40caa232946c5e7e1
z=b"\0"*16
src=f"""// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

/// generated by gen_constants.py: empty-subtree hashes of the Amadeus hbsmt and BLS12-381 constants
library Constants {{
    /// EMPTIES[d*32:(d+1)*32] = hash of an empty subtree rooted at depth d (0..256)
    bytes internal constant EMPTIES = hex"{b"".join(e).hex()}";
    /// -G1 generator, EIP-2537 encoding
    bytes internal constant NEG_G1 = hex"{(z+gx.to_bytes(48,"big")+z+(p-gy).to_bytes(48,"big")).hex()}";
    /// field modulus p and (p-1)/2, 48-byte big-endian
    bytes internal constant P = hex"{p.to_bytes(48,"big").hex()}";
    bytes internal constant P_MINUS_1_HALF = hex"{((p-1)//2).to_bytes(48,"big").hex()}";
}}
"""
open("src/Constants.sol","w").write(src)
